// PythonOpts contains options for Query.Python
type PythonOpts struct {
	// base development container
	Base *Container
	// extra arguments for uv sync command.
	// default value is --frozen --all-extras
	SyncArgs []string
	// extra paths to use while syncing (i.e., paths/files referenced by the pyproject.toml file or other files used due to UV_PROJECT).
	// default value is pyproject.toml and uv.lock
	SyncPaths []string
}

func (r *Query) Python(src *Directory, opts ...PythonOpts) *Python { // python (../../:0:0)
	assertNotNil("src", src)
	q := r.query.Select("python")
	for i := len(opts) - 1; i >= 0; i-- {
		// `base` optional argument
		if !querybuilder.IsZeroValue(opts[i].Base) {
			q = q.Arg("base", opts[i].Base)
		}
		// `syncArgs` optional argument
		if !querybuilder.IsZeroValue(opts[i].SyncArgs) {
			q = q.Arg("syncArgs", opts[i].SyncArgs)
		}
		// `syncPaths` optional argument
		if !querybuilder.IsZeroValue(opts[i].SyncPaths) {
			q = q.Arg("syncPaths", opts[i].SyncPaths)
		}
	}
	q = q.Arg("src", src)

	return &Python{
		query:     q,
		refetchID: r.refetchID,
	}
}
